def function(text,name):
    tokens=r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|/\*[\s\S]*?\*/|//[^\n]*'
    masked=re.sub(tokens,lambda m:' '*len(m.group()),text)
    pattern=r'^(?:static\s+)?(?:inline\s+)?(?:void|VOID|int|INT|INT32|BOOLEAN|NDIS_STATUS|UINT|UINT32|NTSTATUS)\s+'+re.escape(name)+r'\s*\([^;{}]*\)\s*\{'
    found=list(re.finditer(pattern,masked,re.M));require(len(found)==1,'Missing/ambiguous file-IO function '+name)
    start=found[0].start();opening=text.index('{',start);depth=0
    for token in re.finditer(tokens+r'|[{}]',text[opening:]):
        if token.group()=='{':depth+=1
        elif token.group()=='}':
            depth-=1
            if not depth:return text[start:opening+token.end()]
    raise ValueError('Unterminated file-IO function '+name)

def literal_data(source):
    """Read only constant data/aliases; source generator functions never run."""
    values={}
    def value(node):
        if isinstance(node,ast.Name):
            require(node.id in values,'Unknown file-IO literal alias');return values[node.id]
        if isinstance(node,ast.BinOp)and isinstance(node.op,ast.Add):
            left,right=value(node.left),value(node.right)
            require(type(left)is str and type(right)is str,'File-IO concatenation requires strings');return left+right
        if isinstance(node,ast.Dict):return {value(k):value(v)for k,v in zip(node.keys,node.values)}
        if isinstance(node,(ast.Tuple,ast.List)):
            items=[value(v)for v in node.elts];return tuple(items)if isinstance(node,ast.Tuple)else items
        if isinstance(node,ast.Call)and isinstance(node.func,ast.Name)and node.func.id=='tuple'and len(node.args)==1 and not node.keywords:
            item=value(node.args[0]);require(type(item)in(dict,list,tuple),'File-IO tuple literal input');return tuple(item)
        return ast.literal_eval(node)
    for node in ast.parse(source).body:
        require(isinstance(node,(ast.Import,ast.Assign,ast.FunctionDef))or isinstance(node,ast.Expr)and
                isinstance(node.value,ast.Constant)and type(node.value.value)is str,'Unsupported file-IO generator top-level execution')
        if isinstance(node,ast.Import):require(all(a.name in('hashlib','json','re')for a in node.names),'Unexpected file-IO generator import')
        if isinstance(node,ast.Assign):
            require(len(node.targets)==1 and isinstance(node.targets[0],ast.Name),'Unsupported file-IO data assignment')
            require(node.targets[0].id not in values,'Duplicate file-IO data assignment')
            values[node.targets[0].id]=value(node.value)
    return values

def model_data_hash(values):
    return sha(json.dumps({k:v for k,v in values.items()if k!='BASELINE_FUNCTIONS'},sort_keys=True,separators=(',',':')).encode())

def source_macro(text,name):
    result=[]
    for line in text.splitlines():
        if result and result[-1].rstrip().endswith('\\'):
            result.append(line);continue
        if re.match(r'^#define[ \t]+'+re.escape(name)+r'(?=[ \t(])',line):
            require(not result,'Ambiguous calibration source macro '+name);result=[line]
    require(result and not result[-1].rstrip().endswith('\\'),'Missing/unterminated calibration source macro '+name)
    return '\n'.join(result)

def mcu_declarations(texts,values):
    for field in('UINT16 PreCalWriteOffSet;','UINT16 ChGrpMap;'):
        require(texts['adapter'].count(field)==1,'MCU actual adapter storage field differs: '+field)
    declarations=[source_macro(texts['rlm'],n)for n in values['RLM_MACROS']]
    for name in values['EVENT_TYPES']:
        found=re.findall(r'typedef struct _'+re.escape(name)+r'\s*\{[^}]+\}\s*'+re.escape(name)+r',\s*\*P_'+re.escape(name)+r';',texts['rlm'])
        require(len(found)==1,'MCU actual event structure differs: '+name);declarations.extend(found)
    found=re.findall(r'typedef enum _PRE_CAL_TYPE\s*\{[^}]+\}\s*PRE_CAL_TYPE;',texts['cmd'])
    require(len(found)==1,'MCU actual event ID declaration differs');declarations.extend(found)
    for name in('FW_RXD_0','FW_RXD_1','FW_RXD_2'):
        found=re.findall(r'typedef union _'+name+r'\s*\{[\s\S]*?\} '+name+r';',texts['cmd'])
        require(len(found)==2,'MCU endian wire declarations differ: '+name)
        declarations.append('#ifdef RT_BIG_ENDIAN\n'+found[0]+'\n#else\n'+found[1]+'\n#endif')
    found=re.findall(r'typedef struct GNU_PACKED _EVENT_RXD_\s*\{[^}]+\}\s*EVENT_RXD;',texts['cmd'])
    require(len(found)==1,'MCU actual EVENT_RXD differs');declarations.extend(found)
    declarations.extend(source_macro(texts['andes'],n)for n in('GET_EVENT_FW_RXD_LENGTH','GET_EVENT_HDR_ADD_PAYLOAD_TOTAL_LEN'))
    for array,size in(('K_AllFreq','K_ALL_SIZE'),('DPD_AllFreq','DPD_ALL_SIZE')):
        found=re.findall(r'UINT16 '+array+r'\[\] = \{[^}]+\};',texts['tables'])
        require(len(found)==1,'MCU actual calibration table differs: '+array);declarations.extend(found)
        expression='UINT16 '+size+' = (sizeof('+array+') / sizeof(UINT16));'
        require(texts['tables'].count(expression)==1,'MCU actual calibration table length differs: '+array);declarations.append(expression)
    declarations.extend(source_macro(texts['cmd'],n)for n in('RXDCOC_SIZE','TXDPD_SIZE'))
    origin='#define DCOC_FLASH_OFFSET\t\t1024'
    require(texts['chip'].count(origin)==1,'MCU actual Flash origin differs');declarations.append(origin)
    declarations.extend(source_macro(texts['chip'],n)for n in values['CHIP_MACROS'])
    return '\n'.join(declarations)

def actual_functions(inputs,component):
    spec=COMPONENTS[component]
    return {name:function(inputs[spec['source_keys'][key]],name)for name,key in spec['functions'].items()}
def generate_component(inputs,component,profile,old_bodies=None):
    require(component in COMPONENTS and profile in('current','baseline','disabled'),'Typed calibration component/profile required')
    spec=COMPONENTS[component];values=literal_data(inputs[spec['harness_key']])
    for key,expected in(('SOURCE_PATHS',spec['paths']),('FUNCTION_SOURCES',spec['functions']),('BASELINE_COMMIT',BASELINE_COMMIT),('BASELINE_FUNCTIONS_SHA256',spec['baseline_hashes'])):
        exact(values.get(key),expected,'Calibration literal source contract differs: '+component+':'+key)
    require(model_data_hash(values)==spec['model_data_sha256'],'Calibration literal model data differs: '+component)
    for mode,key in(('current','CASE_NAMES'),('baseline','BASELINE_CASES'),('disabled','DISABLED_CASES')):
        exact(list(values[key]),[o['selector']for _,o in CASES if o['component']==component and o['profile']==mode],'Calibration fixed selectors differ: '+component+':'+mode)
    old=values['BASELINE_FUNCTIONS'];stubs=values['DISABLED_STUBS'];stub_hashes=values['DISABLED_STUBS_SHA256'if component=='mcu'else'DISABLED_STUB_SHA256']
    exact({n:sha(b.encode())for n,b in old.items()},spec['baseline_hashes'],'Calibration old body literals differ')
    exact({n:sha(b.encode())for n,b in stubs.items()},stub_hashes,'Calibration disabled stubs differ')
    require(set(old)==set(spec['functions'])-set(values['NEW_FUNCTIONS'])and set(stubs)==set(spec['functions']),'Calibration control function inventory differs')
    if old_bodies is not None:exact(old,old_bodies,'Calibration fixed old bodies differ from independent public Git')
    current=actual_functions(inputs,component);bodies=old if profile=='baseline'else current;fragments=stubs if profile=='disabled'else bodies
    manifest={n:{'source':spec['source_keys'][spec['functions'][n]],'full_body_sha256':sha(b.encode()),'execution':'disabled-stub'if profile=='disabled'else'whole-function','executed_fragment_sha256':sha(fragments[n].encode())}for n,b in bodies.items()}
    for key,literals in spec['source_literals'].items():
        for literal in literals:require(literal in inputs[key],'Calibration configured source invariant differs: '+key)
    local={k:inputs[v]for k,v in spec['source_keys'].items()}
    if component=='mcu':
        admission='\n'.join('if(!strcmp(case_name,'+json.dumps(n)+'))known=1;'for n in values['BASELINE_CASES'if profile=='baseline'else'DISABLED_CASES'if profile=='disabled'else'CASE_NAMES'])
        call='#define CALL_STORE(p,id,data,len) ExtEventPreCalStoreProc(p,id,data'+(')'if profile=='baseline'else',len)')
        validate='#define VALIDATE_STORE(p,n) '+('((void)(p),(void)(n),0)'if profile=='baseline'else'rtmp_precal_records_valid(p,n)')
        prefix=values['PREFIX'].replace('SOURCE_DECLARATIONS',mcu_declarations(local,values))+'\n'+call+'\n'+validate
        main=values['MAIN'].replace('CASE_ADMISSION',admission)
    else:
        for key in('ABI_PROTOTYPES','BASE_PROTOTYPES'):
            for source,declarations in values[key].items():
                for declaration in declarations:require(local[source].count(declaration)==1,'Calibration exact Flash ABI declaration differs')
        prototypes='\n'.join(d for ds in values['BASE_PROTOTYPES'].values()for d in ds)
        if profile!='baseline':prototypes+='\n'+'\n'.join(d for ds in values['ABI_PROTOTYPES'].values()for d in ds)
        require(sha(values['BASELINE_LEGACY_MACRO'].encode())==values['BASELINE_MACRO_SHA256'],'Calibration fixed old macro differs')
        macros=values['BASELINE_LEGACY_MACRO']if profile=='baseline'else source_macro(local['chip_header'],'RT28xx_EEPROM_WRITE16')+'\n'+source_macro(local['chip_header'],'RT28xx_EEPROM_WRITE16_CHECKED')
        if profile=='disabled':macros='#define RT28xx_EEPROM_WRITE16_CHECKED(p,o,v) 0'
        admission='\n'.join('if(!strcmp(case_name,'+json.dumps(n)+'))known=1;'for n in values['BASELINE_CASES'if profile=='baseline'else'DISABLED_CASES'if profile=='disabled'else'CASE_NAMES'])
        require(all(local['hqa_header'].count(m)==1 for m in values['NETWORK_MACROS']),'Calibration HQA network-order declarations differ')
        require(local['hqa_header'].count(values['HQA_FRAME_DECLARATION'])==1 and '#define IOCTLBUFF 2048'in local['ate_header'],'Calibration actual HQA frame geometry differs')
        prefix=values['PREFIX'].replace('SOURCE_MACROS',macros).replace('SOURCE_HQA_FRAME',values['HQA_FRAME_DECLARATION']).replace('SOURCE_HQA_NETWORK','\n'.join(values['NETWORK_MACROS']))+'\n'+prototypes
        main=values['MAIN'].replace('CASE_ADMISSION',admission)
        main=main.replace('RAW_CALL','RtmpFlashWrite(NULL,source,last_offset,last_length);result=0;'if profile=='baseline'else'result=RtmpFlashWriteChecked(NULL,source,last_offset,last_length);')
        main=main.replace('COMMIT_CALL','(void)staged;rtmp_ee_flash_write_all(&a);result=0;'if profile=='baseline'else'result=rtmp_ee_flash_write_image_checked(&a,has("null-input")?NULL:staged,has("length-mismatch")?image_size-1:image_size);')
        main=main.replace('MACRO_CALL','result=0;RT28xx_EEPROM_WRITE16(p,4,0x1234);'if profile=='baseline'else'result=RT28xx_EEPROM_WRITE16_CHECKED(p,4,0x1234);')
    code=prefix+'\n'+'\n'.join(fragments[n]for n in values['BODY_ORDER']if n in fragments)+'\n'+main
    require(type(code)is str and 0<len(code.encode())<=MAX_SOURCE,'Calibration generated C budget differs')
    for name,body in fragments.items():require(code.count(body)==1,'Calibration actual full body omitted/duplicated: '+name)
    return code,manifest

def factory_export_names():
    names={'target-wifi-built.ko','target-wifi-shipped.ko','target-wifi-module.cmd','target-wifi-link.cmd'}
    for label in FACTORY_OBJECTS:names.update(('target-wifi-'+label+'.o','target-wifi-'+label+'.cmd'))
    return names

def io_export_names():
    return {'target-wifi-io-'+label+suffix for label in PARENT_IO_EXTRA_OBJECTS for suffix in('.o','.cmd')}

def parent_export_names():return factory_export_names()|io_export_names()

def parent_reference_from_bytes(inputs,factory_raw,io_raw,artifacts):
    factory=decode_json(factory_raw);io=decode_json(io_raw)
    require(type(factory)is dict and type(io)is dict,'Calibration parents must be JSON objects')
    for report,phase,label in((factory,'final-module-image-reference-bound','Factory49'),(io,'final-module-reference-bound','IO246')):
        require(type(report.get('schema_version'))is int and report['schema_version']==1 and report.get('status')=='PASS'and report.get('profile')=='k2p-4.4'and report.get('phase')==phase,'Calibration requires completed '+label+' parent')
        require(type(report.get('source_sha256'))is dict,'Parent source mapping missing '+label)
    require(set(artifacts)==parent_export_names(),'Calibration exact26 reused export set differs')
    binding=factory.get('module_binding');require(type(binding)is dict and binding.get('status')=='PASS','Factory module binding absent')
    exports=binding.get('exports');require(type(exports)is dict and set(exports)==factory_export_names(),'Factory14 export set differs')
    io_binding=io.get('compiled_binding');require(type(io_binding)is dict and io_binding.get('status')=='PASS','IO compiled binding absent')
    extra=io_binding.get('extra_exports');require(type(extra)is dict and set(extra)==io_export_names(),'IO12 export set differs')
    expected_exports=dict(exports);expected_exports.update(extra)
    exact(expected_exports,{n:sha(d)for n,d in artifacts.items()},'Calibration actual parent export bytes differ')
    require(type(factory.get('kernel_reference'))is dict,'Factory image reference absent')
    image=factory['kernel_reference'].get('image_sha256');require(type(image)is str and re.fullmatch('[0-9a-f]{64}',image),'Factory image digest absent')
    for key in('built_module','shipped_module'):
        require(type(binding.get(key))is dict and type(binding[key].get('ELF'))is dict,'Parent module ELF mapping absent')
    built=sha(artifacts['target-wifi-built.ko']);shipped=sha(artifacts['target-wifi-shipped.ko'])
    require(binding['built_module']['ELF'].get('sha256')==built and binding['shipped_module']['ELF'].get('sha256')==shipped and binding['shipped_module'].get('path')==SHIPPED_MODULE,'Factory actual built/shipped module identity differs')
    ref=io.get('module_reference');require(type(ref)is dict and ref.get('status')=='PASS','IO Factory reference absent')
    require(ref.get('report_sha256')==sha(factory_raw)and ref.get('image_sha256')==image and ref.get('built_module_sha256')==built and ref.get('shipped_module_sha256')==shipped and io_binding.get('built_module_sha256')==built,'Factory/IO same-image/module reference differs')
    exact(ref.get('module_exports_sha256'),exports,'Factory/IO parent14 exports differ')
    require(type(io.get('required_cases'))is list and type(io.get('checks'))is list and len(io['required_cases'])==246 and len(io['checks'])==246 and len(set(io['required_cases']))==246,'IO246 parent case contract absent')
    require(type(factory.get('required_cases'))is list and type(factory.get('checks'))is list and len(factory['required_cases'])==49 and len(factory['checks'])==49,'Factory49 parent case contract absent')
    exact(io.get('source_files'),PARENT_IO_SOURCE_PATHS,'Parent IO20 source path contract differs')
    shared={key:sha(inputs[key].encode())for key in PARENT_IO_SOURCE_PATHS}
    exact(io['source_sha256'],shared,'Calibration/IO20 current source identities differ')
    exact({dest:factory['source_sha256'].get(dest)for key,dest in FACTORY_SOURCE_KEYS.items()},{dest:sha(inputs[key].encode())for key,dest in FACTORY_SOURCE_KEYS.items()},'Calibration/Factory shared source identities differ')
    kernel=factory['kernel_reference']
    require(type(kernel.get('source_sha256'))is dict and kernel['source_sha256'].get('nvram_mtd')==sha(inputs['nvram_mtd'].encode()),'Factory built-in Flash backend source identity differs')
    require(type(kernel.get('required_symbols'))is dict and {'mt_mtd_read_nm_wifi','mt_mtd_write_nm_wifi'}<=set(kernel['required_symbols']),'Factory built-in Flash implementation anchors absent')
    return {'status':'PASS','role':'Reference to separately mandatory Factory49 and IO246 same-image/module proofs',
      'factory_report_file':'target-wifi-factory.json','factory_report_sha256':sha(factory_raw),
      'io_report_file':'target-wifi-file-io.json','io_report_sha256':sha(io_raw),'image_sha256':image,
      'shipped_module_sha256':shipped,'built_module_sha256':built,'parent_exports_sha256':expected_exports,
      'shared_source_sha256':shared,'kernel_reference':kernel,'factory_cases':49,'io_cases':246}

def canonical_command(data):
    require(type(data)is bytes and 0<len(data)<=MAX_COMMAND and b'\0'not in data,'Bounded ordinary compilation command required')
    return data.decode('utf-8').replace('mt7615_ap/../mt7615/','mt7615/')

def command_member(text,path):return re.search(r'(?<![A-Za-z0-9_./+-])'+re.escape(path)+r'(?![A-Za-z0-9_./+-])',text)is not None

def compiled_binding_from_bytes(inputs,artifacts,metadata):
    require(set(artifacts)==parent_export_names(),'Calibration exact reused compiled export set differs')
    built=metadata(artifacts['target-wifi-built.ko'],1);aggregate=canonical_command(artifacts['target-wifi-link.cmd']);selected={}
    for label,(relative,key,names,origin)in COMPILED_OBJECTS.items():
        stem='target-wifi-'+label if origin=='factory'else'target-wifi-io-'+label
        data,command=artifacts[stem+'.o'],artifacts[stem+'.cmd'];text=canonical_command(command)
        require(command_member(text,relative)and command_member(text,relative.removesuffix('.o')+'.c')and command_member(aggregate,relative),'Calibration object/command/source/aggregate binding differs: '+label)
        obj=metadata(data,1);symbols={}
        for name in names:
            require(len(obj['function_symbols'].get(name,[]))==1 and len(built['function_symbols'].get(name,[]))==1 and obj['function_symbols'][name][0]['bytes']>0 and built['function_symbols'][name][0]['bytes']>0,'Calibration implementation symbol absent/ambiguous: '+name)
            symbols[name]={'object_symbol':obj['function_symbols'][name][0],'module_symbol':built['function_symbols'][name][0]}
        selected[label]={'object_file':stem+'.o','command_file':stem+'.cmd','command_sha256':sha(command),'ELF':obj,'source_key':key,'source_sha256':sha(inputs[key].encode()),'required_symbols':list(names),'symbol_bindings':symbols}
    return {'status':'PASS','objects':selected,'built_module_sha256':built['sha256'],'module_aggregate_sha256':sha(artifacts['target-wifi-link.cmd']),'reused_exports_sha256':{n:sha(d)for n,d in artifacts.items()},'source_to_compiled_scope':'Compilation and object-to-module relocation rely on clean locked full-build provenance; no independent compiler replay or whole driver execution is claimed.'}

def require(value,message):
    if not value:raise ValueError(message)

def sha(data):return hashlib.sha256(data).hexdigest()

def exact(left,right,message):
    require(json.dumps(left,sort_keys=True,separators=(',',':'),allow_nan=False)==json.dumps(right,sort_keys=True,separators=(',',':'),allow_nan=False),message)

def decode_json(data):
    def pairs(items):
        result={}
        for key,value in items:
            require(key not in result,'Duplicate calibration JSON key');result[key]=value
        return result
    def constant(value):raise ValueError('Nonfinite calibration JSON number '+value)
    return json.loads(data,object_pairs_hook=pairs,parse_constant=constant)

def read_regular(path,limit):
    try:fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
    except OSError as error:raise ValueError('Calibration source/artifact alias cannot be opened')from error
    try:
        before=os.fstat(fd);require(stat.S_ISREG(before.st_mode)and before.st_nlink==1 and 0<=before.st_size<=limit,'Calibration input must be bounded ordinary single-link file')
        with os.fdopen(fd,'rb',closefd=False)as stream:data=stream.read(limit+1)
        after=os.fstat(fd);require(len(data)==before.st_size and (before.st_dev,before.st_ino,before.st_size,before.st_mtime_ns,before.st_ctime_ns)==(after.st_dev,after.st_ino,after.st_size,after.st_mtime_ns,after.st_ctime_ns),'Calibration input changed during read')
        return data
    finally:os.close(fd)

def validate_contract():
    require(set(COMPONENTS)=={'mcu','flash'}and set(EXPECTED)=={n for n,_ in CASES}and len(CASES)>0 and len(set(n for n,_ in CASES))==len(CASES),'Incomplete calibration fixed component/case contract')
    for name,options in CASES:
        require(type(name)is str and type(options)is dict and set(options)=={'component','profile','selector'}and options['component']in COMPONENTS and options['profile']in('current','baseline','disabled')and name==':'.join(options[k]for k in('component','profile','selector')),'Malformed calibration fixed case')
    require(len(FACTORY_OBJECTS)==5 and len(PARENT_IO_SOURCE_PATHS)==20 and len(PARENT_IO_EXTRA_OBJECTS)==6 and len(parent_export_names())==26,'Calibration parent proof inventory differs')
    require(all(SOURCE_PATHS.get(k)==p for k,p in PARENT_IO_SOURCE_PATHS.items()),'Calibration must preserve parent IO20 aliases')
    require(set(COMPILED_OBJECTS)=={'ee-flash','eeprom','mcu','testmode','hqa'},'Calibration selected object set differs')
    require(len(SOURCE_PATHS)==32 and len(set(SOURCE_PATHS.values()))==32,'Calibration exact unique source inventory differs')
    for component,spec in COMPONENTS.items():
        require(set(spec['paths'])==set(spec['source_keys']) and spec['functions'] and spec['baseline_hashes'],'Calibration component source contract incomplete')
        require(all(SOURCE_PATHS.get(spec['source_keys'][key])==path for key,path in spec['paths'].items()) and spec['harness_key']in SOURCE_PATHS,'Calibration component/global source aliases differ')
        require(set(spec['functions'].values())<=set(spec['paths']) and set(spec['baseline_hashes'])<=set(spec['functions']),'Calibration component function inventory differs')

def validate_records(rows):
    require(type(rows)is list and len(rows)==len(CASES),'Calibration required case count differs')
    for row,(name,options)in zip(rows,CASES):
        require(type(row)is dict and set(row)=={'case','inputs','observed'}and row['case']==name,'Calibration fixed record order/schema differs')
        exact(row['inputs'],options,'Calibration exact typed case inputs differ: '+name)
        exact(row['observed'],EXPECTED[name],'Calibration exact typed case result differs: '+name)

def generate_source(inputs,fixture_root,owner_uid,component,profile='current',old_bodies=None):
    require(component in COMPONENTS and profile in('current','baseline','disabled'),'Calibration typed component/profile required')
    require(type(fixture_root)is str and re.fullmatch('/tmp/k2p-wifi-calibration-integrity-source-[A-Za-z0-9_-]+/'+component+'-'+profile+'-fixture',fixture_root),'Calibration compatibility fixture metadata path differs')
    require(type(owner_uid)is int and 0<=owner_uid<2**32 and set(inputs)==set(SOURCE_PATHS),'Calibration source/UID contract differs')
    return generate_component(inputs,component,profile,old_bodies)

def source_selection(inputs):
    require(command_member(inputs['kernel_makefile'],'-fno-strict-aliasing'),'Calibration kernel aliasing C mode differs')
    require(re.search(r'^CONFIG_RTMP_FLASH_SUPPORT=y$',inputs['wifi_config'],re.M)and re.search(r'^CONFIG_ATE_SUPPORT=y$',inputs['wifi_config'],re.M),'Calibration configured Flash/ATE selection differs')
    require('DRV_NAME = mt_7615e'in inputs['wifi_makefile']and'meta_agent.o'not in inputs['wifi_makefile'],'Calibration configured module/META scope differs')

def parent_reference(inputs,wifi_report,io_report):
    require(wifi_report.parent==io_report.parent,'Calibration parents must share an artifact directory')
    factory_raw=read_regular(wifi_report,MAX_REPORT);io_raw=read_regular(io_report,MAX_REPORT)
    artifacts={n:read_regular(wifi_report.parent/n,MAX_COMMAND if n.endswith('.cmd')else MAX_ELF)for n in parent_export_names()}
    return parent_reference_from_bytes(inputs,factory_raw,io_raw,artifacts),artifacts

def check(trunk,compiler,output,preflight=False,wifi_report=None,io_report=None):
    validate_contract()
    require(type(preflight)is bool and ((preflight and wifi_report is None and io_report is None)or(not preflight and wifi_report is not None and io_report is not None)),'Calibration requires preflight alone or both completed parent proofs')
    config=read_regular(trunk/'.config',MAX_SOURCE).decode()
    require(re.search(r'^CONFIG_LINUXDIR=linux-4\.4\.x$',config,re.M)and re.search(r'^CONFIG_FIRMWARE_PRODUCT_ID="K2P"$',config,re.M),'Calibration gate requires configured K2P4.4')
    inputs={k:read_regular(trunk.parent/p,MAX_SOURCE).decode('utf-8')for k,p in SOURCE_PATHS.items()};source_selection(inputs)
    qemu=shutil.which('qemu-mipsel');require(qemu is not None,'qemu-mipsel required')
    exports={};probes={};manifests={};rows=[]
    with tempfile.TemporaryDirectory(prefix='k2p-wifi-calibration-integrity-source-',dir='/tmp')as temporary:
        base=Path(temporary).resolve()
        for component in COMPONENTS:
            probes[component]={};manifests[component]={}
            for profile in('current','baseline','disabled'):
                fixture=str(base/(component+'-'+profile+'-fixture'));generated,manifest=generate_source(inputs,fixture,os.geteuid(),component,profile)
                stem='target-wifi-calibration-integrity-'+component+'-'+profile;source=base/(stem+'.c');binary=base/stem;source.write_text(generated)
                run=subprocess.run([str(compiler),*FLAGS,str(source),'-o',str(binary)],capture_output=True,text=True,timeout=90)
                require(run.returncode==0,'Calibration static MIPS compile failed: '+run.stdout+run.stderr)
                data=read_regular(binary,MAX_ELF);elf=resident.validate_static_helper(data)
                for name,options in CASES:
                    if options['component']!=component or options['profile']!=profile:continue
                    run=subprocess.run([qemu,str(binary),options['selector']],capture_output=True,text=True,timeout=MAX_COMMAND_SECONDS)
                    require(run.returncode==0 and not run.stderr,'Calibration inert MIPS case failed '+name+': '+run.stdout+run.stderr)
                    rows.append({'case':name,'inputs':options,'observed':decode_json(run.stdout)})
                exports[stem+'.c']=generated.encode();exports[stem]=data;manifests[component][profile]=manifest
                probes[component][profile]={'source_file':stem+'.c','source_sha256':sha(generated.encode()),'binary_file':stem,'binary_sha256':sha(data),'ELF':elf,'compile_flags':list(FLAGS),'fixture_root':fixture,'owner_uid':os.geteuid()}
    validate_records(rows);reference=binding=None
    if not preflight:
        reference,artifacts=parent_reference(inputs,wifi_report,io_report);binding=compiled_binding_from_bytes(inputs,artifacts,spi.inspect_elf)
    output.parent.mkdir(parents=True,exist_ok=True)
    for name,data in exports.items():
        path=output.parent/name;path.write_bytes(data)
        if not name.endswith('.c'):path.chmod(0o755)
    report={'schema_version':1,'status':'PASS','profile':'k2p-4.4','phase':'early-source-only'if preflight else'final-module-reference-bound','execution_role':ROLE,'required_cases':[n for n,_ in CASES],'checks':rows,'source_files':SOURCE_PATHS,'source_sha256':{k:sha(t.encode())for k,t in inputs.items()},'baseline_source_commit':BASELINE_COMMIT,'component_models':COMPONENTS,'function_manifest':manifests,'probes':probes,'module_reference':reference,'compiled_binding':binding,'compiler':str(compiler),'limits':list(LIMITS)}
    output.write_text(json.dumps(report,indent=2)+'\n');print('WiFi calibration integrity: '+str(len(rows))+' inert source/MIPS cases PASS');return report

if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    for name in('trunk','compiler','output'):parser.add_argument('--'+name,type=Path,required=True)
    parser.add_argument('--preflight',action='store_true');parser.add_argument('--wifi-report',type=Path);parser.add_argument('--io-report',type=Path);args=parser.parse_args()
    try:check(args.trunk.resolve(),args.compiler.resolve(),args.output.resolve(),args.preflight,args.wifi_report.resolve()if args.wifi_report else None,args.io_report.resolve()if args.io_report else None)
    except(OSError,ValueError,subprocess.SubprocessError)as error:parser.exit(1,'WiFi calibration integrity validation failed: '+str(error)+'\n')
